import { ArrowRight, Check, Music, Sparkles, Zap } from "lucide-react";
import type { CSSProperties } from "react";
import type { PointerEvent as ReactPointerEvent } from "react";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import { SeoHead } from "../components/SeoHead";
import { usePreferences } from "../hooks/usePreferences";

type SampleProject = {
  icon: typeof Sparkles;
  accent: "violet" | "cyan";
  code: string;
  titleKey: string;
  descriptionKey: string;
  itemKeys: string[];
  linkTo: string;
};

const sampleProjects: SampleProject[] = [
  {
    icon: Sparkles,
    accent: "violet",
    code: "landing.sampleDroneCode",
    titleKey: "landing.sampleDroneTitle",
    descriptionKey: "landing.sampleDroneDescription",
    itemKeys: [
      "landing.sampleDroneItemOne",
      "landing.sampleDroneItemTwo",
      "landing.sampleDroneItemThree",
    ],
    linkTo: "/drone-show",
  },
  {
    icon: Music,
    accent: "cyan",
    code: "landing.samplePianoCode",
    titleKey: "landing.samplePianoTitle",
    descriptionKey: "landing.samplePianoDescription",
    itemKeys: [
      "landing.samplePianoItemOne",
      "landing.samplePianoItemTwo",
      "landing.samplePianoItemThree",
    ],
    linkTo: "/piano",
  },
];

function revealDelay(delayMs: number): CSSProperties {
  return { "--reveal-delay": `${delayMs}ms` } as CSSProperties;
}

export function SamplesPage() {
  const { t } = useTranslation();
  const { motionEnabled } = usePreferences();

  const handleSpotlightMove = (event: ReactPointerEvent<HTMLElement>) => {
    if (!motionEnabled) return;
    const card = event.currentTarget;
    const rect = card.getBoundingClientRect();
    card.style.setProperty("--spot-x", `${Math.round(event.clientX - rect.left)}px`);
    card.style.setProperty("--spot-y", `${Math.round(event.clientY - rect.top)}px`);
  };

  return (
    <>
      <SeoHead titleKey="seo.samplesTitle" descriptionKey="seo.samplesDescription" path="samples" />
      <main className="samples-page">
        {/* Hero */}
      <section className="samples-hero reveal-in">
        <span className="samples-hero__eyebrow">{t("samples.eyebrow")}</span>
        <h1>{t("samples.title")}</h1>
        <p>{t("samples.description")}</p>
      </section>

      {/* 项目卡片网格 */}
      <section className="platform-capability-map samples-grid">
        {sampleProjects.map((project, index) => {
          const Icon = project.icon;
          return (
            <Link
              key={project.linkTo}
              to={project.linkTo}
              className={`platform-capability-card platform-capability-card--${project.accent} reveal-in`}
              style={revealDelay(120 + index * 90)}
              onPointerMove={handleSpotlightMove}
            >
              <div className="platform-capability-card__icon"><Icon size={24} /></div>
              <code>{t(project.code)}</code>
              <h3>{t(project.titleKey)}</h3>
              <p>{t(project.descriptionKey)}</p>
              <ul>
                {project.itemKeys.map((key) => (
                  <li key={key}><Check size={14} />{t(key)}</li>
                ))}
              </ul>
            </Link>
          );
        })}
      </section>

        {/* 底部 CTA */}
        <section className="samples-cta reveal-in" style={revealDelay(360)}>
          <Zap size={20} aria-hidden="true" />
          <p>{t("samples.ctaText")}</p>
          <Link to="/docs" className="main-button main-button--secondary">
            {t("samples.ctaAction")} <ArrowRight size={15} />
          </Link>
        </section>
      </main>
    </>
  );
}
